    highp float fresnel = 0.039999999105930328369140625 + (0.959999978542327880859375 * pow(1.0 - max(0.0, -dot(n, ray)), 5.0));
    highp vec3 r = normalize(reflect(ray, n));
    r = vec3(r.x, abs(r.y), r.z);
    highp vec3 reflection = GetAtmosphere(r);
    highp vec3 part_5 = vec3(0.01600000075995922088623046875, 0.0430000014603137969970703125, 0.122000001370906829833984375);
    highp float part_6 = 0.085000000894069671630859375 * (0.20000000298023223876953125 + ((waterHitPos.y + @DEPTH@) / @DEPTH@));
    highp vec3 scattering = vec3(part_5.x * part_6, part_5.y * part_6, part_5.z * part_6);
    highp vec3 part_7 = vec3(reflection.x * fresnel, reflection.y * fresnel, reflection.z * fresnel);
    highp vec3 color = vec3(part_7.x + scattering.x, part_7.y + scattering.y, part_7.z + scattering.z);
    highp vec3 mapped = AcesTonemap(vec3(color.x * 2.0, color.y * 2.0, color.z * 2.0));
    _return = vec4(mapped.x, mapped.y, mapped.z, 1.0);
}

